class Step11dError(RuntimeError):
    pass


def now_iso():
    return datetime.now().astimezone().isoformat()


def script_dir():
    try:
        return Path(__file__).resolve().parent
    except Exception:
        return Path.cwd()


def out_path(suffix):
    return script_dir() / (OUT_PREFIX + "_" + suffix)


def get_visum():
    try:
        return Visum  # noqa: F821 - supplied by Visum script host
    except NameError:
        if win32com is None:
            raise Step11dError("No running Visum object and pywin32 is unavailable.")
        try:
            return win32com.client.GetActiveObject("Visum.Visum")
        except Exception as e:
            raise Step11dError("Could not attach to running Visum: %r" % (e,))


def sval(v):
    try:
        return "" if v is None else str(v)
    except Exception:
        return repr(v)


def fval(v, default=None):
    try:
        if isinstance(v, str):
            return float(v.strip().replace("\u00a0", "").replace(" ", "").replace(",", "."))
        return float(v)
    except Exception:
        return default


def ival(v, default=None):
    x = fval(v, None)
    if x is None:
        return default
    try:
        return int(round(x))
    except Exception:
        return default


def is_true(v):
    if isinstance(v, bool):
        return v
    s = sval(v).strip().upper()
    if s in ("1", "1.0", "TRUE", "T", "YES", "Y", "ANO", "JA", "ACTIVE"):
        return True
    if s in ("0", "0.0", "FALSE", "F", "NO", "N", "NE", ""):
        return False
    x = fval(v, None)
    return bool(x) if x is not None else False


def finite(v):
    try:
        return math.isfinite(float(v))
    except Exception:
        return False


def att(obj, name, default=""):
    try:
        x = obj.AttValue(name)
        return default if x is None else x
    except Exception:
        return default


def get_all(coll):
    try:
        v = coll.GetAll
        if callable(v):
            v = v()
        if v is not None:
            return list(v)
    except Exception:
        pass
    try:
        return list(coll)
    except Exception:
        return []


def get_multi(coll, attr):
    try:
        return list(coll.GetMultiAttValues(attr, False))
    except Exception:
        try:
            return list(coll.GetMultiAttValues(attr))
        except Exception:
            return []


def matrix_by_no(visum, no):
    try:
        return visum.Net.Matrices.ItemByKey(int(no))
    except Exception:
        return None


def find_matrix_by_code(visum, code):
    target = code.strip().upper()
    for mat in get_all(visum.Net.Matrices):
        if sval(att(mat, "CODE", "")).strip().upper() == target:
            return mat
    return None


def get_link(links, fr, to):
    try:
        return links.ItemByKey(int(fr), int(to))
    except Exception:
        return None


def dseg_flow(link, dseg):
    if link is None:
        return 0.0
    x = fval(att(link, "VOLVEH_DSEG(%s,AP)" % dseg, None), None)
    return 0.0 if x is None else x


def passenger_layers(link):
    n = 0.0
    e = 0.0
    for ds in NATIVE_DSEGS:
        n += dseg_flow(link, ds)
    for ds in EXOG_DSEGS:
        e += dseg_flow(link, ds)
    return n, e


def freight_layers(link):
    x = 0.0
    for ds in FREIGHT_DSEGS:
        x += dseg_flow(link, ds)
    return x


def geh(model, obs):
    m = max(0.0, float(model))
    o = max(0.0, float(obs))
    den = m + o
    if den <= 0:
        return 0.0
    return math.sqrt(2.0 * (m - o) * (m - o) / den)


def demand_side_geh_min(fixed_exog, obs):
    e = max(0.0, float(fixed_exog))
    o = max(0.0, float(obs))
    if e <= o:
        return 0.0
    return geh(e, o)


def write_csv(path, fields, rows):
    with path.open("w", encoding="utf-8-sig", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(fields), delimiter=";", extrasaction="ignore")
        w.writeheader()
        for row in rows:
            w.writerow(row)


def write_json(path, obj):
    with path.open("w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2, sort_keys=True)


def read_csv_auto(path):
    with Path(path).open("r", encoding="utf-8-sig", newline="") as f:
        sample = f.read(8192)
        f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t")
            delimiter = dialect.delimiter
        except Exception:
            first = sample.splitlines()[0] if sample.splitlines() else ""
            if ";" in first and first.count(";") >= first.count(","):
                delimiter = ";"
            elif "\t" in first:
                delimiter = "\t"
            else:
                delimiter = ","
        return list(csv.DictReader(f, delimiter=delimiter))


def _has_idp_authority(c):
    return bool(c and c.exists() and c.is_dir() and (c / "R1_IDP_DIST_KM_TARGET_CURVES_V1.csv").exists())


def _extract_embedded_authority(target_parent):
    import base64
    import zipfile
    import io
    raw = base64.b64decode("".join(EMBEDDED_IDP_AUTHORITY_ZIP_B64.split()))
    import hashlib
    got = hashlib.sha256(raw).hexdigest()
    if got != EMBEDDED_IDP_AUTHORITY_ZIP_SHA256:
        raise Step11dError("Embedded IDP authority zip SHA256 mismatch: %s" % got)
    target_parent = Path(target_parent)
    target_parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
        for info in zf.infolist():
            rel = Path(info.filename)
            if rel.is_absolute() or ".." in rel.parts:
                raise Step11dError("Unsafe embedded IDP authority path: %s" % info.filename)
            dest = target_parent / rel
            if info.is_dir():
                dest.mkdir(parents=True, exist_ok=True)
            else:
                dest.parent.mkdir(parents=True, exist_ok=True)
                with zf.open(info, "r") as src, open(str(dest), "wb") as dst:
                    dst.write(src.read())
    return target_parent / "R1_IDP_DISTRIBUTION_AUTHORITY_V1"


def resolve_authority_dir():
    env = os.environ.get("R1_IDP_AUTHORITY_DIR", "").strip()
    candidates = []
    if env:
        candidates.append(Path(env))
    candidates.extend([
        script_dir() / "R1_IDP_DISTRIBUTION_AUTHORITY_V1",
        script_dir(),
        Path.cwd() / "R1_IDP_DISTRIBUTION_AUTHORITY_V1",
        Path.cwd(),
        script_dir().parent / "R1_IDP_DISTRIBUTION_AUTHORITY_V1",
        Path.cwd().parent / "R1_IDP_DISTRIBUTION_AUTHORITY_V1",
    ])
    for c in candidates:
        if _has_idp_authority(c):
            return c

    # v1.1 fallback: if only the .py file was copied, materialize the embedded
    # authority folder next to the script and use it. This writes only local CSV
    # authority files; it does not touch the Visum model.
    extracted = _extract_embedded_authority(script_dir())
    if _has_idp_authority(extracted):
        try:
            with open(str(out_path("idp_authority_autorecovery.txt")), "w", encoding="utf-8") as f:
                f.write("AUTOEXTRACTED_EMBEDDED_IDP_AUTHORITY\n")
                f.write("authority_dir=%s\n" % extracted)
        except Exception:
            pass
        return extracted

    raise Step11dError(
        "Could not find or extract R1_IDP_DIST_KM_TARGET_CURVES_V1.csv. "
        "Keep R1_IDP_DISTRIBUTION_AUTHORITY_V1 next to this script or set R1_IDP_AUTHORITY_DIR."
    )

def normalize_points(points):
    by_x = {}
    for x, y in points:
        xf = fval(x, None)
        yf = fval(y, None)
        if xf is None or yf is None or not finite(xf) or not finite(yf):
            continue
        if xf not in by_x or abs(yf) > abs(by_x[xf]):
            by_x[xf] = max(0.0, yf)
    out = sorted(by_x.items())
    if len(out) < 2:
        return []
    # Normalize density area on its available support.
    area = 0.0
    for i in range(1, len(out)):
        x0, y0 = out[i - 1]
        x1, y1 = out[i]
        dx = x1 - x0
        if dx > 0:
            area += dx * (y0 + y1) / 2.0
    if area > 0:
        out = [(x, y / area) for x, y in out]
    return out


def interp(points, x):
    if not points:
        return 0.0
    if x < points[0][0] or x > points[-1][0]:
        return 0.0
    if x == points[0][0]:
        return points[0][1]
    xs = [p[0] for p in points]
    pos = bisect_left(xs, x)
    if pos < len(points) and points[pos][0] == x:
        return points[pos][1]
    if pos <= 0 or pos >= len(points):
        return 0.0
    x0, y0 = points[pos - 1]
    x1, y1 = points[pos]
    if x1 == x0:
        return y0
    t = (x - x0) / (x1 - x0)
    return y0 + t * (y1 - y0)


def integrate_interval(points, low, high, moment=False):
    if not points or high <= low:
        return 0.0
    # Outside support density is zero; still include interval edges for correct tails.
    finite_high = high
    if high == float("inf"):
        finite_high = max(points[-1][0], low)
    if finite_high <= low:
        return 0.0
    xs = [low, finite_high]
    for x, _ in points:
        if low < x < finite_high:
            xs.append(x)
    xs = sorted(set(xs))
    total = 0.0
    for i in range(1, len(xs)):
        x0 = xs[i - 1]
        x1 = xs[i]
        y0 = interp(points, x0)
        y1 = interp(points, x1)
        dx = x1 - x0
        if dx <= 0:
            continue
        if not moment:
            total += dx * (y0 + y1) / 2.0
        else:
            # exact first moment for linearly interpolated y between endpoints
            total += dx * (x0 * y0 + (x0 * y1 + x1 * y0) / 2.0 + x1 * y1) / 3.0
    return total


def curve_stats(points, bins):
    masses = []
    for low, high, label in bins:
        masses.append((label, integrate_interval(points, low, high, False)))
    s = sum(v for _, v in masses)
    if s > 0:
        shares = [(label, v / s) for label, v in masses]
    else:
        shares = [(label, 0.0) for label, _ in masses]
    total_mass = integrate_interval(points, points[0][0], points[-1][0], False) if points else 0.0
    moment = integrate_interval(points, points[0][0], points[-1][0], True) if points else 0.0
    mean = moment / total_mass if total_mass > 0 else None
    return shares, mean


def load_component_curves(path):
    rows = read_csv_auto(path)
    grouped = {}
    meta = {}
    for r in rows:
        comp = sval(r.get("component", "")).strip()
        if not comp:
            continue
        metric = sval(r.get("metric", "")).strip()
        x = fval(r.get("x", None), None)
        y = fval(r.get("density", None), None)
        if x is None or y is None:
            continue
        grouped.setdefault(comp, []).append((x, y))
        if comp not in meta:
            meta[comp] = {
                "component": comp,
                "family": sval(r.get("family", "")),
                "socio": sval(r.get("socio", "")),
                "metric": metric,
                "source": sval(r.get("source", "")),
                "from_km": sval(r.get("from_km", "")),
                "to_km": sval(r.get("to_km", "")),
            }
    curves = {}
    for comp, pts in grouped.items():
        curves[comp] = normalize_points(pts)
    return curves, meta


def load_long_basis(path):
    rows = read_csv_auto(path)
    grouped = {}
    meta = {}
    for r in rows:
        comp = sval(r.get("component", "")).strip()
        purpose = sval(r.get("basis_purpose", "")).strip()
        if not comp or not purpose:
            continue
        key = comp + "\u0000" + purpose
        x = fval(r.get("x", None), None)
        y = fval(r.get("density", None), None)
        if x is None or y is None:
            continue
        grouped.setdefault(key, []).append((x, y))
        if key not in meta:
            meta[key] = {
                "basis_key": key,
                "component": comp,
                "family": sval(r.get("family", "")),
                "socio": sval(r.get("socio", "")),
                "basis_purpose": purpose,
                "basis_status": sval(r.get("basis_status", "")),
                "mixture_status": sval(r.get("mixture_status", "")),
                "source": sval(r.get("source", "")),
                "from_km": sval(r.get("from_km", "")),
                "to_km": sval(r.get("to_km", "")),
            }
    curves = {}
    for key, pts in grouped.items():
        curves[key] = normalize_points(pts)
    return curves, meta


def read_matrix_values(mat):
    try:
        vals = mat.GetValues()
        return [list(row) for row in vals], "GetValues"
    except Exception as e:
        raise Step11dError("Could not read matrix %s with GetValues: %r" % (sval(att(mat, "NO", "")), e))


def matrix_inventory_row(mat, expected_no=None, label=""):
    if mat is None:
        return {
            "label": label,
            "expected_no": expected_no,
            "found": 0,
            "no": "",
            "code": "",
            "name": "",
            "matrix_type": "",
            "object_type_ref": "",
            "rows": "",
            "cols": "",
            "total_nonnegative": "",
            "negative_cells": "",
            "nonfinite_cells": "",
        }
    total, neg, nonfinite = matrix_total(mat)
    return {
        "label": label,
        "expected_no": expected_no,
        "found": 1,
        "no": ival(att(mat, "NO", None), ""),
        "code": sval(att(mat, "CODE", "")),
        "name": sval(att(mat, "NAME", "")),
        "matrix_type": sval(att(mat, "MATRIXTYPE", "")),
        "object_type_ref": sval(att(mat, "OBJECTTYPEREF", "")),
        "rows": sval(att(mat, "NUMROWS", "")),
        "cols": sval(att(mat, "NUMCOLS", "")),
        "total_nonnegative": total,
        "negative_cells": neg,
        "nonfinite_cells": nonfinite,
    }


def matrix_total(mat):
    vals, _ = read_matrix_values(mat)
    total = 0.0
    negative = 0
    nonfinite = 0
    for row in vals:
        for v in row:
            x = fval(v, None)
            if x is None or not finite(x):
                nonfinite += 1
                continue
            if x < 0:
                negative += 1
                x = 0.0
            total += x
    return total, negative, nonfinite


def bin_label_for_value(x, bins):
    for idx, (low, high, label) in enumerate(bins):
        if high == float("inf"):
            if x > low:
                return label
        elif idx == 0:
            if x >= low and x <= high:
                return label
        else:
            if x > low and x <= high:
                return label
    return None


def compute_matrix_distribution(mat, class_matrix_values, bins, condition_low=None, condition_high=None):
    vals, method = read_matrix_values(mat)
    if len(vals) != len(class_matrix_values):
        raise Step11dError("Matrix dimension mismatch for %s" % sval(att(mat, "NO", "")))

    bin_sums = {label: 0.0 for _, _, label in bins}
    total = 0.0
    conditioned_total = 0.0
    outside_low = 0.0
    outside_high = 0.0
    weighted_sum = 0.0
    conditioned_weighted_sum = 0.0
    negative_cells = 0
    nonfinite_cells = 0

    for i, row in enumerate(vals):
        drow = class_matrix_values[i]
        if len(row) != len(drow):
            raise Step11dError("Matrix column mismatch for row %d" % (i + 1))
        for j, v in enumerate(row):
            x = fval(v, None)
            c = fval(drow[j], None)
            if x is None or c is None or not finite(x) or not finite(c):
                nonfinite_cells += 1
                continue
            if x < 0:
                negative_cells += 1
                x = 0.0
            if x == 0.0:
                continue
            total += x
            weighted_sum += x * c
            in_condition = True
            if condition_low is not None and c < condition_low:
                in_condition = False
                outside_low += x
            if condition_high is not None and c > condition_high:
                in_condition = False
                outside_high += x
            if in_condition:
                conditioned_total += x
                conditioned_weighted_sum += x * c
                label = bin_label_for_value(c, bins)
                if label is not None:
                    bin_sums[label] += x

    rows = []
    for low, high, label in bins:
        value = bin_sums[label]
        rows.append({
            "bin_label": label,
            "bin_low": low,
            "bin_high": "INF" if high == float("inf") else high,
            "volume": value,
            "share_conditioned": value / conditioned_total if conditioned_total > 0 else 0.0,
            "share_total": value / total if total > 0 else 0.0,
        })

    meta = {
        "read_method": method,
        "total_volume": total,
        "conditioned_volume": conditioned_total,
        "outside_low_volume": outside_low,
        "outside_high_volume": outside_high,
        "outside_low_share_total": outside_low / total if total > 0 else 0.0,
        "outside_high_share_total": outside_high / total if total > 0 else 0.0,
        "mean_all": weighted_sum / total if total > 0 else None,
        "mean_conditioned": conditioned_weighted_sum / conditioned_total if conditioned_total > 0 else None,
        "negative_cells": negative_cells,
        "nonfinite_cells": nonfinite_cells,
    }
    return rows, meta


def component_weight_rows(visum, components, target_group):
    rows = []
    total_weight = 0.0
    for comp in components:
        no = COMPONENT_MATRIX_NOS.get(comp)
        mat = matrix_by_no(visum, no) if no is not None else None
        if mat is not None:
            total, neg, nonfinite = matrix_total(mat)
        else:
            total, neg, nonfinite = 0.0, 0, 0
        rows.append({
            "target_group": target_group,
            "component": comp,
            "matrix_no": no,
            "matrix_found": 1 if mat is not None else 0,
            "matrix_code": sval(att(mat, "CODE", "")) if mat is not None else "",
            "matrix_name": sval(att(mat, "NAME", "")) if mat is not None else "",
            "raw_weight_matrix_total": total,
            "negative_cells": neg,
            "nonfinite_cells": nonfinite,
            "normalized_weight": 0.0,
            "weight_policy": "PERSON_COMPONENT_MATRIX_TOTAL",
        })
        total_weight += max(0.0, total)
    positive = [r for r in rows if fval(r["raw_weight_matrix_total"], 0.0) > 0]
    if total_weight > 0:
        for r in rows:
            r["normalized_weight"] = max(0.0, fval(r["raw_weight_matrix_total"], 0.0)) / total_weight
    elif rows:
        # Non-authoritative fallback; final status will flag this.
        w = 1.0 / len(rows)
        for r in rows:
            r["normalized_weight"] = w
            r["weight_policy"] = "FALLBACK_UNIFORM_NO_POSITIVE_COMPONENT_MATRIX_TOTALS"
    return rows


def build_composite_target(target_group, comp_rows, component_curves, bins):
    bin_values = {label: 0.0 for _, _, label in bins}
    component_target_rows = []
    weighted_mean = 0.0
    available_weight = 0.0

    for wr in comp_rows:
        comp = wr["component"]
        w = fval(wr["normalized_weight"], 0.0) or 0.0
        pts = component_curves.get(comp)
        if not pts:
            component_target_rows.append({
                "target_group": target_group,
                "component": comp,
                "status": "MISSING_IDP_COMPONENT_CURVE",
            })
            continue
        shares, mean = curve_stats(pts, bins)
        available_weight += w
        if mean is not None:
            weighted_mean += w * mean
        for label, share in shares:
            bin_values[label] += w * share
            component_target_rows.append({
                "target_group": target_group,
                "component": comp,
                "bin_label": label,
                "target_share_component": share,
                "component_weight": w,
                "weighted_contribution": w * share,
                "component_mean": mean,
                "status": "OK",
            })

    if available_weight > 0 and abs(available_weight - 1.0) > 1e-9:
        for k in list(bin_values.keys()):
            bin_values[k] /= available_weight
        weighted_mean /= available_weight

    composite_rows = []
    for low, high, label in bins:
        composite_rows.append({
            "target_group": target_group,
            "bin_label": label,
            "bin_low": low,
            "bin_high": high,
            "target_share": bin_values.get(label, 0.0),
            "metric": "DIST_KM",
            "authority_use": "BACKEND_DIST_ONLY",
            "provenance": "IDP_COMPONENT_CURVES_WEIGHTED_BY_LIVE_PERSON_COMPONENT_TOTALS",
            "target_mean": weighted_mean if available_weight > 0 else "",
        })
    return composite_rows, component_target_rows, weighted_mean if available_weight > 0 else None


def compare_distribution(dseg, target_group, model_rows, model_meta, target_rows, target_mean):
    by_label = {r["bin_label"]: r for r in target_rows}
    rows = []
    l1 = 0.0
    l2 = 0.0
    for mr in model_rows:
        label = mr["bin_label"]
        tr = by_label.get(label, {})
        target = fval(tr.get("target_share", 0.0), 0.0) or 0.0
        model = fval(mr.get("share_conditioned", 0.0), 0.0) or 0.0
        diff = model - target
        l1 += abs(diff)
        l2 += diff * diff
        out = dict(mr)
        out.update({
            "dseg": dseg,
            "target_group": target_group,
            "target_share": target,
            "share_diff_model_minus_target": diff,
            "abs_share_diff": abs(diff),
        })
        rows.append(out)
    mean_model = model_meta.get("mean_conditioned")
    summary = {
        "dseg": dseg,
        "target_group": target_group,
        "total_volume": model_meta.get("total_volume"),
        "conditioned_volume": model_meta.get("conditioned_volume"),
        "outside_high_share_total": model_meta.get("outside_high_share_total"),
        "mean_model_conditioned": mean_model,
        "mean_target": target_mean,
        "mean_delta_model_minus_target": (mean_model - target_mean) if (mean_model is not None and target_mean is not None) else "",
        "l1_distance_half": 0.5 * l1,
        "rmse_share": math.sqrt(l2 / len(model_rows)) if model_rows else "",
        "bc_direction_hint": bc_direction_hint(mean_model, target_mean),
    }
    return rows, summary


def bc_direction_hint(model_mean, target_mean):
    if model_mean is None or target_mean is None:
        return "NO_HINT"
    delta = model_mean - target_mean
    rel = delta / target_mean if target_mean else 0.0
    if abs(rel) < 0.03:
        return "KEEP_OR_VERY_SMALL_STEP"
    if delta > 0:
        return "MODEL_TOO_LONG__INCREASE_DISTANCE_DECAY_BOUND_STEP"
    return "MODEL_TOO_SHORT__DECREASE_DISTANCE_DECAY_BOUND_STEP"


def tff_scaffold_status(visum):
    rows = []
    selected = None
    for idx, op in enumerate(get_all(visum.Procedures.Operations), start=1):
        comment = sval(att(op, "COMMENT", ""))
        otype = sval(att(op, "OPERATIONTYPE", ""))
        active = sval(att(op, "ACTIVE", ""))
        row = {
            "index": idx,
            "operation_type": otype,
            "active": active,
            "code": sval(att(op, "CODE", "")),
            "comment": comment,
            "procedure_variant": "",
            "procedure_variant_read_status": "NOT_READ",
        }
        params = None
        try:
            params = op.DemandMatrixCorrectionParameters
        except Exception:
            params = None
        if params is not None:
            try:
                row["procedure_variant"] = sval(params.AttValue("ProcedureVariant"))
                row["procedure_variant_read_status"] = "READ"
            except Exception as e:
                row["procedure_variant_read_status"] = "ERROR: %r" % e
        rows.append(row)
        if "66" in otype and row["procedure_variant"].upper() == "TFLOWFUZZY":
            selected = row
        elif any(h in comment for h in TFF_COMMENT_HINTS):
            selected = row
    status = {
        "candidate_count": len(rows),
        "selected": selected,
        "status": "PASS_INACTIVE_TFLOWFUZZY_SCAFFOLD" if selected and not is_true(selected.get("active")) and selected.get("procedure_variant", "").upper() == "TFLOWFUZZY" else "REVIEW_TFLOWFUZZY_SCAFFOLD",
        "operations": rows,
    }
    return status


def countlocation_rows(visum):
    links = visum.Net.Links
    out = []
    for cl in get_all(visum.Net.CountLocations):
        role = sval(att(cl, "R1_ROLE", "")).strip().upper()
        active = is_true(att(cl, "R1_ACTIVE", 0))
        ready = is_true(att(cl, "R1_RPDI_READY", 0))
        if role != COUNT_ROLE or not active or not ready:
            continue
        no = ival(att(cl, "NO", None), None)
        obs = fval(att(cl, "R1_OBS_RPDI", None), None)
        fr = ival(att(cl, "FROMNODENO", None), None)
        to = ival(att(cl, "TONODENO", None), None)
        if obs is None or fr is None or to is None:
            continue
        lf = get_link(links, fr, to)
        lr = get_link(links, to, fr)
        nf, ef = passenger_layers(lf)
        nr, er = passenger_layers(lr)
        ff = freight_layers(lf)
        frt = freight_layers(lr)
        native = nf + nr
        exog = ef + er
        freight = ff + frt
        passenger = native + exog
        allveh = passenger + freight
        floor_geh = demand_side_geh_min(exog, obs)
        row = {
            "countlocation_no": no,
            "obs_id": sval(att(cl, "R1_OBS_ID", "")) or sval(att(cl, "CODE", "")) or "CL_%s" % no,
            "code": sval(att(cl, "CODE", "")),
            "name": sval(att(cl, "NAME", "")),
            "from_node_no": fr,
            "to_node_no": to,
            "r1_dir": sval(att(cl, "R1_DIR", "")),
            "obs_rpdi": obs,
            "native_fwd": nf,
            "native_rev": nr,
            "exog_fwd": ef,
            "exog_rev": er,
            "freight_fwd": ff,
            "freight_rev": frt,
            "native_both": native,
            "exog_both": exog,
            "freight_both_diagnostic": freight,
            "passenger_model_both": passenger,
            "all_vehicle_with_freight_diagnostic": allveh,
            "geh_passenger": geh(passenger, obs),
            "geh_all_vehicle_diagnostic": geh(allveh, obs),
            "demand_side_geh_floor": floor_geh,
            "demand_tff_active_from_link_uda_fwd": att(lf, "R1_TFF_ACTIVE", "") if lf is not None else "",
            "demand_tff_active_from_link_uda_rev": att(lr, "R1_TFF_ACTIVE", "") if lr is not None else "",
        }
        out.append(row)
    return out


def summarize_geh(rows):
    vals = sorted([fval(r.get("geh_passenger"), None) for r in rows if fval(r.get("geh_passenger"), None) is not None])
    if not vals:
        return {}
    def pct(p):
        if not vals:
            return None
        pos = (len(vals) - 1) * p
        lo = int(math.floor(pos))
        hi = int(math.ceil(pos))
        if lo == hi:
            return vals[lo]
        return vals[lo] * (hi - pos) + vals[hi] * (pos - lo)
    return {
        "profiles": len(vals),
        "geh_lt_5": sum(1 for v in vals if v < 5.0),
        "geh_lt_10": sum(1 for v in vals if v < 10.0),
        "share_geh_lt_5": sum(1 for v in vals if v < 5.0) / float(len(vals)),
        "share_geh_lt_10": sum(1 for v in vals if v < 10.0) / float(len(vals)),
        "geh_median": pct(0.5),
        "geh_p90": pct(0.9),
        "geh_max": max(vals),
    }


def load_class_matrix(mat):
    vals, method = read_matrix_values(mat)
    if len(vals) != EXPECTED_ZONE_COUNT or any(len(r) != EXPECTED_ZONE_COUNT for r in vals):
        raise Step11dError("Classification matrix %s does not have 681x681 values." % sval(att(mat, "NO", "")))
    out = []
    nonfinite = 0
    negative = 0
    for row in vals:
        rr = []
        for v in row:
            x = fval(v, None)
            if x is None or not finite(x):
                nonfinite += 1
                x = 0.0
            if x < 0:
                negative += 1
                x = 0.0
            rr.append(float(x))
        out.append(rr)
    return out, {"read_method": method, "nonfinite_cells": nonfinite, "negative_cells": negative}


def find_time_matrix(visum):
    env = os.environ.get("R1_TIME_MATRIX_NO", "").strip()
    if env:
        mat = matrix_by_no(visum, int(env))
        if mat is not None:
            return mat, "ENV_R1_TIME_MATRIX_NO"
    for code in ("R1_OSRM_TIME_MIN", "R1_OSRM_TIME", "OSRM_TIME_MIN", "R1_TIME_MIN"):
        mat = find_matrix_by_code(visum, code)
        if mat is not None:
            return mat, "CODE_%s" % code
    mat = matrix_by_no(visum, 9001)
    if mat is not None:
        return mat, "FALLBACK_MATRIX_NO_9001"
    return None, "NOT_FOUND"


def project_simplex(v):
    # Euclidean projection onto {w >= 0, sum w = 1}.
    n = len(v)
    if n == 0:
        return []
    u = sorted(v, reverse=True)
    cssv = []
    s = 0.0
    rho = -1
    theta = 0.0
    for i, ui in enumerate(u):
        s += ui
        cssv.append(s)
        t = (s - 1.0) / (i + 1)
        if ui - t > 0:
            rho = i
            theta = t
    if rho < 0:
        return [1.0 / n] * n
    return [max(x - theta, 0.0) for x in v]


def fit_simplex_basis(target, basis_vectors, iterations=2000):
    k = len(basis_vectors)
    m = len(target)
    if k == 0 or m == 0:
        return [], None
    w = [1.0 / k] * k
    # Conservative step; dimensions are tiny, robustness is preferred.
    step = 0.25
    for _ in range(iterations):
        pred = [0.0] * m
        for j in range(k):
            bj = basis_vectors[j]
            for i in range(m):
                pred[i] += w[j] * bj[i]
        grad = [0.0] * k
        for j in range(k):
            bj = basis_vectors[j]
            g = 0.0
            for i in range(m):
                g += 2.0 * (pred[i] - target[i]) * bj[i]
            grad[j] = g
        w = project_simplex([w[j] - step * grad[j] for j in range(k)])
    pred = [0.0] * m
    for j in range(k):
        for i in range(m):
            pred[i] += w[j] * basis_vectors[j][i]
    loss = sum((pred[i] - target[i]) ** 2 for i in range(m))
    return w, {"sse": loss, "rmse": math.sqrt(loss / m) if m else None, "predicted": pred}


def main():
    created_at = now_iso()
    warnings = []
    outputs = {}

    visum = get_visum()

    # 0) Scaffold status
    tff_status = tff_scaffold_status(visum)
    p = out_path("tflowfuzzy_scaffold_status.json")
    write_json(p, tff_status)
    outputs["tflowfuzzy_scaffold_status"] = str(p)

    # 1) Traffic count baseline
    traffic_rows = countlocation_rows(visum)
    traffic_fields = [
        "countlocation_no", "obs_id", "code", "name", "from_node_no", "to_node_no", "r1_dir",
        "obs_rpdi", "native_fwd", "native_rev", "exog_fwd", "exog_rev",
        "freight_fwd", "freight_rev", "native_both", "exog_both",
        "freight_both_diagnostic", "passenger_model_both", "all_vehicle_with_freight_diagnostic",
        "geh_passenger", "geh_all_vehicle_diagnostic", "demand_side_geh_floor",
        "demand_tff_active_from_link_uda_fwd", "demand_tff_active_from_link_uda_rev",
    ]
    p = out_path("traffic_count_baseline.csv")
    write_csv(p, traffic_fields, traffic_rows)
    outputs["traffic_count_baseline"] = str(p)
    geh_summary = summarize_geh(traffic_rows)

    # 2) Matrix inventories and classification matrices
    dist_mat = find_matrix_by_code(visum, OSRM_MATRIX_CODE)
    if dist_mat is None:
        raise Step11dError("Missing classification matrix CODE=%s. Run/verify 11c v2.2 first." % OSRM_MATRIX_CODE)
    dist_values, dist_readback = load_class_matrix(dist_mat)

    time_mat, time_matrix_source = find_time_matrix(visum)
    time_values = None
    time_readback = None
    if time_mat is not None:
        try:
            time_values, time_readback = load_class_matrix(time_mat)
        except Exception as e:
            warnings.append("TIME diagnostic matrix found but not readable: %r" % e)
            time_mat = None
            time_values = None
            time_readback = None
    else:
        warnings.append("TIME diagnostic skipped: no time matrix found.")

    matrix_inv_rows = []
    matrix_inv_rows.append(matrix_inventory_row(dist_mat, "CODE:" + OSRM_MATRIX_CODE, "DIST_CLASSIFICATION"))
    if time_mat is not None:
        matrix_inv_rows.append(matrix_inventory_row(time_mat, ival(att(time_mat, "NO", None), ""), "TIME_DIAGNOSTIC_CLASSIFICATION"))
    for dseg, no in NATIVE_MATRIX_NOS.items():
        matrix_inv_rows.append(matrix_inventory_row(matrix_by_no(visum, no), no, dseg))
    for comp, no in COMPONENT_MATRIX_NOS.items():
        matrix_inv_rows.append(matrix_inventory_row(matrix_by_no(visum, no), no, comp))
    p = out_path("matrix_inventory.csv")
    write_csv(p, [
        "label", "expected_no", "found", "no", "code", "name", "matrix_type", "object_type_ref",
        "rows", "cols", "total_nonnegative", "negative_cells", "nonfinite_cells",
    ], matrix_inv_rows)
    outputs["matrix_inventory"] = str(p)

    # 3) IDP authority
    auth_dir = resolve_authority_dir()
    dist_curve_path = auth_dir / "R1_IDP_DIST_KM_TARGET_CURVES_V1.csv"
    time_curve_path = auth_dir / "R1_IDP_TIME_MIN_DIAGNOSTIC_CURVES_V1.csv"
    long_basis_path = auth_dir / "R1_IDP_LONG_DIST_KM_BASIS_V1.csv"

    dist_curves, dist_curve_meta = load_component_curves(dist_curve_path)
    time_curves, time_curve_meta = ({}, {})
    if time_curve_path.exists():
        time_curves, time_curve_meta = load_component_curves(time_curve_path)

    weight_rows = []
    weight_rows.extend(component_weight_rows(visum, WORK_SCHOOL_COMPONENTS, "WORK_SCHOOL"))
    weight_rows.extend(component_weight_rows(visum, SERVICE_COMPONENTS, "SERVICE"))
    p = out_path("idp_composite_component_weights.csv")
    write_csv(p, [
        "target_group", "component", "matrix_no", "matrix_found", "matrix_code", "matrix_name",
        "raw_weight_matrix_total", "normalized_weight", "weight_policy", "negative_cells", "nonfinite_cells",
    ], weight_rows)
    outputs["idp_composite_component_weights"] = str(p)

    if any(r.get("weight_policy", "").startswith("FALLBACK") for r in weight_rows):
        warnings.append("At least one IDP composite uses fallback component weights. Review component matrix inventory.")

    ws_weight_rows = [r for r in weight_rows if r["target_group"] == "WORK_SCHOOL"]
    serv_weight_rows = [r for r in weight_rows if r["target_group"] == "SERVICE"]
    ws_target_rows, ws_component_target_rows, ws_target_mean = build_composite_target("WORK_SCHOOL", ws_weight_rows, dist_curves, DIST_BINS_0_100)
    serv_target_rows, serv_component_target_rows, serv_target_mean = build_composite_target("SERVICE", serv_weight_rows, dist_curves, DIST_BINS_0_100)
    composite_target_rows = ws_target_rows + serv_target_rows
    component_target_rows = ws_component_target_rows + serv_component_target_rows

    p = out_path("idp_dist_composite_targets.csv")
    write_csv(p, [
        "target_group", "bin_label", "bin_low", "bin_high", "target_share", "metric",
        "authority_use", "provenance", "target_mean",
    ], composite_target_rows)
    outputs["idp_dist_composite_targets"] = str(p)

    p = out_path("idp_dist_component_target_bins.csv")
    write_csv(p, [
        "target_group", "component", "bin_label", "target_share_component", "component_weight",
        "weighted_contribution", "component_mean", "status",
    ], component_target_rows)
    outputs["idp_dist_component_target_bins"] = str(p)

    # 3b) Atomic component-level DIST targets.
    # These are the behavioral calibration authority for b,c.  Family-level
    # composites above are retained only as assignment-family guardrails.
    atomic_component_target_rows = []
    for comp in sorted(dist_curves.keys()):
        pts = dist_curves.get(comp)
        meta0 = dist_curve_meta.get(comp, {})
        shares, mean0 = curve_stats(pts, DIST_BINS_0_100)
        for (label, share), (low, high, _) in zip(shares, DIST_BINS_0_100):
            atomic_component_target_rows.append({
                "component": comp,
                "family": meta0.get("family", ""),
                "socio": meta0.get("socio", ""),
                "metric": "DIST_KM",
                "authority_use": "COMPONENT_CALIBRATION_TARGET",
                "source": meta0.get("source", ""),
                "from_km": meta0.get("from_km", ""),
                "to_km": meta0.get("to_km", ""),
                "bin_label": label,
                "bin_low": low,
                "bin_high": high,
                "target_share": share,
                "target_mean": mean0,
            })
    p = out_path("idp_dist_component_atomic_targets.csv")
    write_csv(p, [
        "component", "family", "socio", "metric", "authority_use", "source",
        "from_km", "to_km", "bin_label", "bin_low", "bin_high",
        "target_share", "target_mean",
    ], atomic_component_target_rows)
    outputs["idp_dist_component_atomic_targets"] = str(p)

    target_by_group = {
        "WORK_SCHOOL": (ws_target_rows, ws_target_mean),
        "SERVICE": (serv_target_rows, serv_target_mean),
    }

    # 4) Current DIST behavior by native DSeg
    model_dist_bin_rows = []
    dist_compare_rows = []
    dist_summary_rows = []
    for dseg, no in NATIVE_MATRIX_NOS.items():
        mat = matrix_by_no(visum, no)
        if mat is None:
            warnings.append("Native matrix %s no=%s not found." % (dseg, no))
            continue
        rows, meta = compute_matrix_distribution(
            mat, dist_values, DIST_BINS_0_100, condition_low=0.0, condition_high=100.0
        )
        target_group = DSEG_TARGET_GROUP.get(dseg, "")
        for r in rows:
            rr = dict(r)
            rr.update({
                "dseg": dseg,
                "matrix_no": no,
                "target_group": target_group,
                "metric": "DIST_KM",
                "classification": "R1_OSRM_DIST_KM",
                "condition": "0_100_KM_CONDITIONAL",
            })
            model_dist_bin_rows.append(rr)
        if target_group in target_by_group:
            target_rows, target_mean = target_by_group[target_group]
            comp_rows, summ = compare_distribution(dseg, target_group, rows, meta, target_rows, target_mean)
            for cr in comp_rows:
                cr.update({"matrix_no": no, "metric": "DIST_KM", "authority_use": "BACKEND_DIST_ONLY"})
                dist_compare_rows.append(cr)
            dist_summary_rows.append(summ)
        else:
            dist_summary_rows.append({
                "dseg": dseg,
                "target_group": target_group,
                "total_volume": meta.get("total_volume"),
                "conditioned_volume": meta.get("conditioned_volume"),
                "outside_high_share_total": meta.get("outside_high_share_total"),
                "mean_model_conditioned": meta.get("mean_conditioned"),
                "mean_target": "",
                "mean_delta_model_minus_target": "",
                "l1_distance_half": "",
                "rmse_share": "",
                "bc_direction_hint": "NO_BACKEND_IDP_TARGET_IN_11D",
            })

    p = out_path("model_dist_baseline_by_dseg.csv")
    write_csv(p, [
        "dseg", "matrix_no", "target_group", "metric", "classification", "condition",
        "bin_label", "bin_low", "bin_high", "volume", "share_conditioned", "share_total",
    ], model_dist_bin_rows)
    outputs["model_dist_baseline_by_dseg"] = str(p)

    p = out_path("model_dist_vs_idp_by_dseg.csv")
    write_csv(p, [
        "dseg", "matrix_no", "target_group", "metric", "authority_use", "bin_label", "bin_low", "bin_high",
        "volume", "share_conditioned", "share_total", "target_share", "share_diff_model_minus_target", "abs_share_diff",
    ], dist_compare_rows)
    outputs["model_dist_vs_idp_by_dseg"] = str(p)

    p = out_path("model_dist_vs_idp_summary.csv")
    write_csv(p, [
        "dseg", "target_group", "total_volume", "conditioned_volume", "outside_high_share_total",
        "mean_model_conditioned", "mean_target", "mean_delta_model_minus_target",
        "l1_distance_half", "rmse_share", "bc_direction_hint",
    ], dist_summary_rows)
    outputs["model_dist_vs_idp_summary"] = str(p)

    # 4b) Current DIST behavior by atomic person component.
    component_model_dist_rows = []
    component_dist_compare_rows = []
    component_dist_summary_rows = []
    component_dist_target_by_comp = {}
    for comp, pts in dist_curves.items():
        shares, mean0 = curve_stats(pts, DIST_BINS_0_100)
        component_dist_target_by_comp[comp] = ([{
            "target_group": comp,
            "bin_label": label,
            "bin_low": low,
            "bin_high": high,
            "target_share": share,
            "metric": "DIST_KM",
            "authority_use": "COMPONENT_CALIBRATION_TARGET",
            "provenance": "R1_IDP_DIST_KM_TARGET_CURVES_V1_ATOMIC_COMPONENT",
            "target_mean": mean0,
        } for (label, share), (low, high, _) in zip(shares, DIST_BINS_0_100)], mean0)

    for comp, no in COMPONENT_MATRIX_NOS.items():
        mat = matrix_by_no(visum, no)
        family = comp.split("_", 1)[0] if "_" in comp else comp
        if mat is None:
            warnings.append("Component matrix %s no=%s not found." % (comp, no))
            component_dist_summary_rows.append({
                "component": comp,
                "family": family,
                "matrix_no": no,
                "target_status": "MATRIX_NOT_FOUND",
                "total_volume": "",
                "conditioned_volume": "",
                "outside_high_share_total": "",
                "mean_model_conditioned": "",
                "mean_target": "",
                "mean_delta_model_minus_target": "",
                "l1_distance_half": "",
                "rmse_share": "",
                "bc_direction_hint": "NO_HINT",
            })
            continue

        if comp in component_dist_target_by_comp:
            rows, meta = compute_matrix_distribution(
                mat, dist_values, DIST_BINS_0_100, condition_low=0.0, condition_high=100.0
            )
            for r in rows:
                rr = dict(r)
                rr.update({
                    "component": comp,
                    "family": family,
                    "matrix_no": no,
                    "metric": "DIST_KM",
                    "classification": "R1_OSRM_DIST_KM",
                    "condition": "0_100_KM_CONDITIONAL",
                    "target_status": "ACTIVE_COMPONENT_DIST_TARGET",
                })
                component_model_dist_rows.append(rr)
            target_rows0, target_mean0 = component_dist_target_by_comp[comp]
            cmp_rows, cmp_summary = compare_distribution(comp, comp, rows, meta, target_rows0, target_mean0)
            for cr in cmp_rows:
                cr.update({
                    "component": comp,
                    "family": family,
                    "matrix_no": no,
                    "metric": "DIST_KM",
                    "authority_use": "COMPONENT_CALIBRATION_TARGET",
                })
                component_dist_compare_rows.append(cr)
            cmp_summary.update({
                "component": comp,
                "family": family,
                "matrix_no": no,
                "target_status": "ACTIVE_COMPONENT_DIST_TARGET",
            })
            component_dist_summary_rows.append(cmp_summary)
        elif comp in LONG_COMPONENTS:
            rows, meta = compute_matrix_distribution(
                mat, dist_values, LONG_BINS_100_200, condition_low=100.0, condition_high=200.0
            )
            for r in rows:
                rr = dict(r)
                rr.update({
                    "component": comp,
                    "family": "LONG",
                    "matrix_no": no,
                    "metric": "DIST_KM",
                    "classification": "R1_OSRM_DIST_KM",
                    "condition": "100_200_KM_CONDITIONAL",
                    "target_status": "LONG_BASIS_PENDING_NOT_BACKEND_TARGET",
                })
                component_model_dist_rows.append(rr)
            component_dist_summary_rows.append({
                "component": comp,
                "family": "LONG",
                "matrix_no": no,
                "target_status": "LONG_BASIS_PENDING_NOT_BACKEND_TARGET",
                "total_volume": meta.get("total_volume"),
                "conditioned_volume": meta.get("conditioned_volume"),
                "outside_high_share_total": meta.get("outside_high_share_total"),
                "mean_model_conditioned": meta.get("mean_conditioned"),
                "mean_target": "",
                "mean_delta_model_minus_target": "",
                "l1_distance_half": "",
                "rmse_share": "",
                "bc_direction_hint": "PENDING_LONG_BASIS_FREEZE",
            })
        else:
            rows, meta = compute_matrix_distribution(
                mat, dist_values, DIST_BINS_0_100, condition_low=0.0, condition_high=100.0
            )
            for r in rows:
                rr = dict(r)
                rr.update({
                    "component": comp,
                    "family": family,
                    "matrix_no": no,
                    "metric": "DIST_KM",
                    "classification": "R1_OSRM_DIST_KM",
                    "condition": "0_100_KM_CONDITIONAL",
                    "target_status": "NO_DOMESTIC_IDP_TARGET",
                })
                component_model_dist_rows.append(rr)
            component_dist_summary_rows.append({
                "component": comp,
                "family": family,
                "matrix_no": no,
                "target_status": "NO_DOMESTIC_IDP_TARGET",
                "total_volume": meta.get("total_volume"),
                "conditioned_volume": meta.get("conditioned_volume"),
                "outside_high_share_total": meta.get("outside_high_share_total"),
                "mean_model_conditioned": meta.get("mean_conditioned"),
                "mean_target": "",
                "mean_delta_model_minus_target": "",
                "l1_distance_half": "",
                "rmse_share": "",
                "bc_direction_hint": "NO_BACKEND_IDP_TARGET",
            })

    p = out_path("component_model_dist_baseline.csv")
    write_csv(p, [
        "component", "family", "matrix_no", "metric", "classification", "condition", "target_status",
        "bin_label", "bin_low", "bin_high", "volume", "share_conditioned", "share_total",
    ], component_model_dist_rows)
    outputs["component_model_dist_baseline"] = str(p)

    p = out_path("component_model_dist_vs_idp.csv")
    write_csv(p, [
        "component", "family", "matrix_no", "target_group", "metric", "authority_use",
        "bin_label", "bin_low", "bin_high", "volume", "share_conditioned", "share_total",
        "target_share", "share_diff_model_minus_target", "abs_share_diff",
    ], component_dist_compare_rows)
    outputs["component_model_dist_vs_idp"] = str(p)

    p = out_path("component_model_dist_vs_idp_summary.csv")
    write_csv(p, [
        "component", "family", "matrix_no", "target_status", "target_group",
        "total_volume", "conditioned_volume", "outside_high_share_total",
        "mean_model_conditioned", "mean_target", "mean_delta_model_minus_target",
        "l1_distance_half", "rmse_share", "bc_direction_hint",
    ], component_dist_summary_rows)
    outputs["component_model_dist_vs_idp_summary"] = str(p)

    # 5) TIME diagnostics only, when a time matrix exists.
    time_compare_rows = []
    time_summary_rows = []
    if time_mat is not None and time_values is not None and time_curves:
        ws_t_rows, _, ws_t_mean = build_composite_target("WORK_SCHOOL", ws_weight_rows, time_curves, TIME_BINS_DIAG)
        serv_t_rows, _, serv_t_mean = build_composite_target("SERVICE", serv_weight_rows, time_curves, TIME_BINS_DIAG)
        time_target_by_group = {
            "WORK_SCHOOL": (ws_t_rows, ws_t_mean),
            "SERVICE": (serv_t_rows, serv_t_mean),
        }
        for dseg, no in NATIVE_MATRIX_NOS.items():
            target_group = DSEG_TARGET_GROUP.get(dseg, "")
            if target_group not in time_target_by_group:
                continue
            mat = matrix_by_no(visum, no)
            if mat is None:
                continue
            rows, meta = compute_matrix_distribution(
                mat, time_values, TIME_BINS_DIAG, condition_low=0.0, condition_high=None
            )
            target_rows, target_mean = time_target_by_group[target_group]
            comp_rows, summ = compare_distribution(dseg, target_group, rows, meta, target_rows, target_mean)
            for cr in comp_rows:
                cr.update({
                    "matrix_no": no,
                    "metric": "TIME_MIN",
                    "authority_use": "DIAGNOSTIC_ONLY_NOT_BACKEND",
                    "provenance_flag": "TIME_UNCONDITIONED_BY_DISTANCE",
                    "time_matrix_source": time_matrix_source,
                })
                time_compare_rows.append(cr)
            summ.update({
                "metric": "TIME_MIN",
                "authority_use": "DIAGNOSTIC_ONLY_NOT_BACKEND",
                "provenance_flag": "TIME_UNCONDITIONED_BY_DISTANCE",
                "time_matrix_source": time_matrix_source,
            })
            time_summary_rows.append(summ)

    p = out_path("model_time_diagnostic_vs_idp.csv")
    write_csv(p, [
        "dseg", "matrix_no", "target_group", "metric", "authority_use", "provenance_flag", "time_matrix_source",
        "bin_label", "bin_low", "bin_high", "volume", "share_conditioned", "share_total",
        "target_share", "share_diff_model_minus_target", "abs_share_diff",
    ], time_compare_rows)
    outputs["model_time_diagnostic_vs_idp"] = str(p)

    p = out_path("model_time_diagnostic_summary.csv")
    write_csv(p, [
        "dseg", "target_group", "metric", "authority_use", "provenance_flag", "time_matrix_source",
        "total_volume", "conditioned_volume", "outside_high_share_total", "mean_model_conditioned",
        "mean_target", "mean_delta_model_minus_target", "l1_distance_half", "rmse_share", "bc_direction_hint",
    ], time_summary_rows)
    outputs["model_time_diagnostic_summary"] = str(p)

    # 6) LONG 100-200 km baseline and basis fit candidate.
    long_model_rows = []
    long_fit_rows = []
    long_fit_summary = {}
    cl_mat = matrix_by_no(visum, NATIVE_MATRIX_NOS["NATIVE_CL"])
    if cl_mat is not None:
        cl_rows, cl_meta = compute_matrix_distribution(
            cl_mat, dist_values, LONG_BINS_100_200, condition_low=100.0, condition_high=200.0
        )
        for r in cl_rows:
            rr = dict(r)
            rr.update({
                "dseg": "NATIVE_CL",
                "matrix_no": NATIVE_MATRIX_NOS["NATIVE_CL"],
                "metric": "DIST_KM",
                "classification": "R1_OSRM_DIST_KM",
                "condition": "100_200_KM_CONDITIONAL",
            })
            long_model_rows.append(rr)
        if long_basis_path.exists() and cl_meta.get("conditioned_volume", 0.0) > 0:
            long_curves, long_meta = load_long_basis(long_basis_path)
            basis_vectors = []
            basis_keys = []
            basis_bin_rows = []
            for key, pts in sorted(long_curves.items()):
                shares, mean = curve_stats(pts, LONG_BINS_100_200)
                vec = [s for _, s in shares]
                if sum(vec) <= 0:
                    continue
                basis_keys.append(key)
                basis_vectors.append(vec)
                for (label, share), (low, high, _) in zip(shares, LONG_BINS_100_200):
                    basis_bin_rows.append({
                        "basis_key": key,
                        "component": long_meta.get(key, {}).get("component", ""),
                        "socio": long_meta.get(key, {}).get("socio", ""),
                        "basis_purpose": long_meta.get(key, {}).get("basis_purpose", ""),
                        "bin_label": label,
                        "bin_low": low,
                        "bin_high": high,
                        "basis_share": share,
                        "basis_mean": mean,
                    })
            target_vec = [fval(r.get("share_conditioned", 0.0), 0.0) or 0.0 for r in cl_rows]
            weights, fit_meta = fit_simplex_basis(target_vec, basis_vectors, iterations=2000)
            for key, w in zip(basis_keys, weights):
                m = long_meta.get(key, {})
                long_fit_rows.append({
                    "basis_key": key,
                    "component": m.get("component", ""),
                    "socio": m.get("socio", ""),
                    "basis_purpose": m.get("basis_purpose", ""),
                    "weight_candidate": w,
                    "basis_status": m.get("basis_status", ""),
                    "mixture_status": "CANDIDATE_FROM_11D_BASELINE_NOT_FROZEN",
                })
            if fit_meta is not None:
                long_fit_summary = {
                    "status": "PASS_LONG_BASIS_FIT_CANDIDATE_EXPORTED",
                    "basis_count": len(basis_keys),
                    "bins": [b[2] for b in LONG_BINS_100_200],
                    "target_vector": target_vec,
                    "predicted_vector": fit_meta.get("predicted"),
                    "rmse": fit_meta.get("rmse"),
                    "sse": fit_meta.get("sse"),
                    "native_cl_total_volume": cl_meta.get("total_volume"),
                    "native_cl_100_200_volume": cl_meta.get("conditioned_volume"),
                    "native_cl_100_200_share_total": (cl_meta.get("conditioned_volume", 0.0) / cl_meta.get("total_volume", 1.0)) if cl_meta.get("total_volume", 0.0) > 0 else 0.0,
                    "note": "Candidate only. Freeze in later step only after review.",
                }
        else:
            long_fit_summary = {
                "status": "SKIPPED_LONG_BASIS_FIT_NO_CL_100_200_VOLUME_OR_MISSING_BASIS",
                "native_cl_total_volume": cl_meta.get("total_volume"),
                "native_cl_100_200_volume": cl_meta.get("conditioned_volume"),
            }

    p = out_path("long_cl_baseline_100_200_bins.csv")
    write_csv(p, [
        "dseg", "matrix_no", "metric", "classification", "condition",
        "bin_label", "bin_low", "bin_high", "volume", "share_conditioned", "share_total",
    ], long_model_rows)
    outputs["long_cl_baseline_100_200_bins"] = str(p)

    p = out_path("long_dist_basis_fit_candidate.csv")
    write_csv(p, [
        "basis_key", "component", "socio", "basis_purpose", "weight_candidate", "basis_status", "mixture_status",
    ], long_fit_rows)
    outputs["long_dist_basis_fit_candidate"] = str(p)

    p = out_path("long_dist_basis_fit_summary.json")
    write_json(p, long_fit_summary)
    outputs["long_dist_basis_fit_summary"] = str(p)

    # 7) b,c direction recommendation summary.
    bc_rows = []
    for row in dist_summary_rows:
        if row.get("target_group") in ("WORK_SCHOOL", "SERVICE"):
            bc_rows.append({
                "scope": row.get("dseg"),
                "target_group": row.get("target_group"),
                "metric": "DIST_KM",
                "mean_model_conditioned": row.get("mean_model_conditioned"),
                "mean_target": row.get("mean_target"),
                "mean_delta_model_minus_target": row.get("mean_delta_model_minus_target"),
                "l1_distance_half": row.get("l1_distance_half"),
                "bounded_candidate_direction": row.get("bc_direction_hint"),
                "candidate_policy": "DIRECTION_ONLY_NO_VISUM_WRITE_NO_BC_CHANGE",
            })
    p = out_path("bc_direction_recommendation.csv")
    write_csv(p, [
        "scope", "target_group", "metric", "mean_model_conditioned", "mean_target",
        "mean_delta_model_minus_target", "l1_distance_half", "bounded_candidate_direction", "candidate_policy",
    ], bc_rows)
    outputs["bc_direction_recommendation"] = str(p)

    component_bc_rows = []
    try:
        for row in component_dist_summary_rows:
            if row.get("target_status") == "ACTIVE_COMPONENT_DIST_TARGET":
                component_bc_rows.append({
                    "component": row.get("component"),
                    "family": row.get("family"),
                    "matrix_no": row.get("matrix_no"),
                    "metric": "DIST_KM",
                    "mean_model_conditioned": row.get("mean_model_conditioned"),
                    "mean_target": row.get("mean_target"),
                    "mean_delta_model_minus_target": row.get("mean_delta_model_minus_target"),
                    "l1_distance_half": row.get("l1_distance_half"),
                    "bounded_candidate_direction": row.get("bc_direction_hint"),
                    "candidate_policy": "COMPONENT_LEVEL_DIRECTION_ONLY_NO_VISUM_WRITE_NO_BC_CHANGE",
                })
    except Exception:
        component_bc_rows = []
    p = out_path("component_bc_direction_recommendation.csv")
    write_csv(p, [
        "component", "family", "matrix_no", "metric", "mean_model_conditioned", "mean_target",
        "mean_delta_model_minus_target", "l1_distance_half", "bounded_candidate_direction", "candidate_policy",
    ], component_bc_rows)
    outputs["component_bc_direction_recommendation"] = str(p)

    # Final status.
    status = "PASS_11D_BASELINE_DIAGNOSTICS_READ_ONLY"
    if tff_status.get("status") != "PASS_INACTIVE_TFLOWFUZZY_SCAFFOLD":
        status = "REVIEW_11D_TFLOWFUZZY_SCAFFOLD"
    if not traffic_rows:
        status = "REVIEW_11D_NO_TRAFFIC_COUNT_ROWS"
    if any(r.get("weight_policy", "").startswith("FALLBACK") for r in weight_rows):
        status = "REVIEW_11D_COMPONENT_WEIGHT_FALLBACK"

    summary = {
        "step": STEP,
        "created_at": created_at,
        "final_status": status,
        "model_modified": False,
        "model_saved": False,
        "matrix_correction_executed": False,
        "assignment_executed": False,
        "tflowfuzzy_scaffold_status": tff_status.get("status"),
        "traffic_geh_summary": geh_summary,
        "authority_dir": str(auth_dir),
        "dist_classification_matrix": {
            "code": OSRM_MATRIX_CODE,
            "matrix_no": ival(att(dist_mat, "NO", None), None),
            "readback": dist_readback,
        },
        "time_diagnostic_matrix": {
            "found": time_mat is not None,
            "source": time_matrix_source,
            "matrix_no": ival(att(time_mat, "NO", None), None) if time_mat is not None else None,
            "readback": time_readback,
            "backend_constraint": False,
        },
        "idp_contract": {
            "backend_metric": "DIST_KM",
            "time_min_role": "DIAGNOSTIC_ONLY__NOT_BACKEND_CONSTRAINT",
            "component_dist_targets": "ACTIVE for WORK_* + SERV_* + SCHOOL atomic component matrices 9101..9110 and 9117",
            "family_composites": "DIAGNOSTIC_GUARDRAIL_ONLY for NATIVE_CW/CW_noT and NATIVE_CS/CS_noT",
            "long_target": "DIST 100-200 basis fit candidate only, not frozen in 11d",
            "foreign_target": "NO_DOMESTIC_IDP_TARGET",
        },
        "dist_summary_rows": dist_summary_rows,
        "component_dist_summary_rows": component_dist_summary_rows,
        "long_fit_summary": long_fit_summary,
        "warnings": warnings,
        "outputs": outputs,
    }
    p = out_path("summary.json")
    write_json(p, summary)
    outputs["summary"] = str(p)

    lines = [
        "R1 STEP 11d v1.3 - component-level IDP DIST behavior diagnostics",
        "=================================================================",
        "",
        "Final status: %s" % status,
        "",
        "MODEL MODIFIED: NO",
        "MODEL SAVED AUTOMATICALLY: NO",
        "MATRIX CORRECTION EXECUTED: NO",
        "ASSIGNMENT EXECUTED: NO",
        "",
        "TFlowFuzzy scaffold:",
        "  status: %s" % tff_status.get("status"),
        "",
        "Traffic GEH baseline:",
        "  profiles: %s" % geh_summary.get("profiles", 0),
        "  GEH < 5: %s" % geh_summary.get("geh_lt_5", ""),
        "  GEH < 10: %s" % geh_summary.get("geh_lt_10", ""),
        "  median GEH: %s" % geh_summary.get("geh_median", ""),
        "  P90 GEH: %s" % geh_summary.get("geh_p90", ""),
        "",
        "IDP contract applied:",
        "  Backend/guardrail: DIST_KM only.",
        "  TIME_MIN: diagnostic only, provenance TIME_UNCONDITIONED_BY_DISTANCE when exported.",
        "  Component targets: WORK_* + SERV_* + SCHOOL atomic DIST curves.",
        "  Family composites: retained only as guardrail diagnostics, not final b,c authority.",
        "  CL: LONG 100-200 km basis-fit candidate only, not frozen here.",
        "  CF/FOREIGN: no domestic IDP target.",
        "",
        "Next step:",
        "  Review component_model_dist_vs_idp_summary.csv and component_bc_direction_recommendation.csv,",
        "  plus long_dist_basis_fit_summary.json.  Do not execute TFlowFuzzy manually.",
        "  A later step can bind counts + DIST distribution or freeze LONG basis weights.",
        "",
        "Outputs:",
    ]
    for k, v in sorted(outputs.items()):
        lines.append("  %s: %s" % (k, v))
    if warnings:
        lines.extend(["", "Warnings:"])
        for w in warnings:
            lines.append("  - %s" % w)
    p = out_path("recommendation.txt")
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")
    outputs["recommendation"] = str(p)

    print(
        "R1 STEP 11d v1.1 done: %s | profiles=%s | DIST summaries=%d | LONG fit=%s"
        % (status, geh_summary.get("profiles", 0), len(dist_summary_rows), long_fit_summary.get("status", ""))
    )


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        try:
            out_path("fatal_error.txt").write_text(
                now_iso() + "\n" + repr(e) + "\n\n" + traceback.format_exc(),
                encoding="utf-8",
            )
        except Exception:
            pass
        print("R1 STEP 11d v1.1 FATAL: %r" % (e,))
        raise
